    if not pts:
        return out
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    # Cross formed by extending the 2x2 zero marker's rows and columns.
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if c0 <= c <= c1:
                out[r][c] = 0
            elif r0 <= r <= r1:
                out[r][c] = 2 if grid[r][c] == 2 else 0
    return out

