def transform(grid):
    out=[row[:] for row in grid]
    zeros=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==0]
    if not zeros: return out
    r0=min(r for r,c in zeros); c0=min(c for r,c in zeros); c1=max(c for r,c in zeros)
    # Erase the two full columns defined by the marker.
    for row in out:
        for c in range(c0, c1 + 1):
            row[c] = 0
    # Each row with marker pixels contains a sparse 2-signal; erase its other
    # cells while preserving those 2s. Demos show the patch occupies two rows.
    for r in range(r0, r1 + 1):
        for c, value in enumerate(grid[r]):
            if not c0 <= c <= c1:
                out[r][c] = 2 if value == 2 else 0
    return out

